const sampleDocs=DEMO_KNOWLEDGE.docs.map(d=>{const content=knowledgeMarkdown(d.id);return {id:d.id,title:d.title,summary:d.summary,type:'虚构制度',version:d.version,category:d.category,date:DEMO_KNOWLEDGE.effectiveDate,size:(new Blob([content]).size/1024).toFixed(1)+' KB',content,clauses:d.clauses,builtin:true};});
function makeSeed(){
 const expenses=[];
 for(let i=0;i<76;i++){
  const month=i<48?'10':i<66?'09':'08';const day=i<48?22-Math.floor(i/2.3):28-(i%18);
  const category=cats[i%5],person=people[i%8],dept=depts[i%5];
  const status=i<14?'pending':i<20?'returned':i<28?'approved':'paid';
  const issue=i<20&&i%4===0?'缺少行程附件':i<20&&i%7===0?'需核对发票抬头':'';
  const amount=Math.round((360+((i*733+430)%7200)+(i%3)*.36)*100)/100;
  const date=`2026-${month}-${String(Math.max(day,1)).padStart(2,'0')}`;
  const title=[`${['郑州','洛阳','焦作','武汉'][i%4]}项目出差费用`,'项目驻场住宿费用','客户交流接待费用','部门办公用品采购','项目培训及服务费用'][i%5];
  expenses.push({id:'BX2026'+String(1076-i).padStart(5,'0'),title,person,dept,category,amount,date,status,issue,invoiceNo:'24611000'+String(300000+i),company:'星澜能源科技有限公司（虚构）',files:[{id:'seed-'+i,name:i%2?'电子发票.pdf':'差旅费用凭证.pdf',size:228300,sample:true}],note:'用于演示的报销记录，不代表真实企业业务。',mine:i%8===0,history:[{text:'员工提交报销申请',date:date+' 09:30'},{text:issue?'规则预审发现待核对项':'规则预审完成，待财务复核',date:date+' 09:31'},...(status==='approved'||status==='paid'?[{text:'财务模拟审核通过',date:date+' 15:20'}]:[]),...(status==='returned'?[{text:'退回补充：附件信息不完整',date:date+' 15:20'}]:[]),...(status==='paid'?[{text:'示例记录：已支付（非真实付款）',date:date+' 16:40'}]:[])]});
 }
 const logs=Array.from({length:64},(_,i)=>{const topic=i<24?0:i<40?1:i<52?2:i<59?3:4;return{id:'QA'+(1000+i),person:people[i%8],dept:depts[i%5],question:questionText[topic],topic:topics[topic],date:'2026-10-'+String(22-Math.floor(i/4)).padStart(2,'0'),resolved:i%9!==0,answer:policyAnswer(questionText[topic]).text,source:policyAnswer(questionText[topic]).source,sample:true};});
 return {expenses,logs,docs:sampleDocs,receipts:[],draft:null,knowledgeVersion:DEMO_KNOWLEDGE.version};
}
function policyAnswer(q,context={}){return knowledgeAnswer(q,context);}
const STORE='expense-workbench-v1';let state;
try{const raw=JSON.parse(localStorage.getItem(STORE));state=raw&&Array.isArray(raw.expenses)&&Array.isArray(raw.logs)&&Array.isArray(raw.docs)&&Array.isArray(raw.receipts)?raw:makeSeed();}catch{state=makeSeed();}
let view='overview',role='finance',period='2026-10',department='all',statusFilter='all',searchQuery='',currentPage=1,selectedId=null,chatMessages=[],newFiles=[...(state.draft?.files||[])],invoiceFiles=[],knowledgeFiles=[],lastSubmitted=null,storageWarning=false,formMemory={...(state.draft?.values||{})},revisionId=state.draft?.revisionId||null;
let chatContext={role:DEMO_KNOWLEDGE.defaultRole,city:''},knowledgeQuery='';
function migrateKnowledge(){
 if(state.knowledgeVersion===DEMO_KNOWLEDGE.version)return;
 const builtins=new Set(['policy-travel','policy-invoice','policy-process',...sampleDocs.map(d=>d.id)]);
 state.docs=[...state.docs.filter(d=>!builtins.has(d.id)),...sampleDocs];
 state.logs=state.logs.map(l=>{if(!l.sample||l.source?.startsWith('财务人工补充'))return l;const answer=policyAnswer(l.question);return {...l,answer:answer.text,source:answer.source,citations:answer.citations};});
 state.knowledgeVersion=DEMO_KNOWLEDGE.version;
 try{localStorage.setItem(STORE,JSON.stringify(state));}catch{storageWarning=true;}
}
migrateKnowledge();
let dbPromise;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('expense-workbench-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return dbPromise;}
async function putFile(file){const id=crypto.randomUUID();const base=await db();await new Promise((resolve,reject)=>{const tx=base.transaction('files','readwrite');tx.objectStore('files').put({id,file});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});return{id,name:file.name,size:file.size,type:file.type};}
async function getFile(id){const base=await db();return new Promise((resolve,reject)=>{const r=base.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result?.file);r.onerror=()=>reject(r.error);});}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch{storageWarning=true;toast('浏览器存储空间不足，请先导出数据；本次修改仅在当前页面有效。');return false;}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
function stamp(){return new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,16);}
function selectedRows({mine=false}={}){return state.expenses.filter(r=>(!mine||r.mine)&&(period==='quarter'?r.date>='2026-08-01'&&r.date<='2026-10-31':r.date.startsWith(period))&&(department==='all'||r.dept===department));}
function selectedLogs(){return state.logs.filter(r=>(period==='quarter'?r.date>='2026-08-01'&&r.date<='2026-10-31':r.date.startsWith(period))&&(department==='all'||r.dept===department));}
function sum(rows){return Math.round(rows.reduce((t,r)=>t+r.amount,0)*100)/100;}
function statusBadge(s){return`<span class="badge ${s==='pending'?'warn':s==='returned'?'red':s==='paid'?'gray':''}"><i class="dot"></i>${({pending:'待审核',returned:'已退回',approved:'待支付',paid:'已支付'})[s]||s}</span>`;}
function heading(title,subtitle,actions=''){return`<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function filters(){return`<select class="compact-select" id="dept-filter" aria-label="部门筛选"><option value="all">全部部门</option>${depts.map(d=>`<option ${department===d?'selected':''}>${d}</option>`).join('')}</select><select class="compact-select" id="period-filter" aria-label="统计时间"><option value="2026-10" ${period==='2026-10'?'selected':''}>2026 年 10 月</option><option value="2026-09" ${period==='2026-09'?'selected':''}>2026 年 9 月</option><option value="quarter" ${period==='quarter'?'selected':''}>近三个月</option></select>`;}
function shell(){
 const financeNav=[['overview','dashboard','工作台总览'],['expenses','receipt','报销预审'],['invoices','invoice','发票中心'],['logs','chat','咨询日志'],['insights','chart','问题洞察']];
 const employeeNav=[['employee','dashboard','我的工作台'],['consult','chat','报销咨询'],['new','plus','发起报销'],['mine','receipt','我的报销']];
 document.getElementById('sidebar').innerHTML=`<a class="brand" href="#" data-view="${role==='finance'?'overview':'employee'}"><span class="brand-mark">${icon('receipt')}</span><span>报销有数<small>EXPENSE WORKSPACE</small></span></a><div class="workspace"><span class="square">财</span><div>财务预审工作台<br><span class="muted" style="font-size:10px">${role==='finance'?'财务管理空间':'员工服务空间'}</span></div>${icon('down')}</div><div class="nav-label">${role==='finance'?'财务工作台':'员工工作台'}</div><nav aria-label="主导航" class="nav-group">${(role==='finance'?financeNav:employeeNav).map(([id,ic,title])=>`<button class="nav-link ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}${title}${id==='expenses'?`<span class="nav-count">${state.expenses.filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">支持与配置</div><nav aria-label="支持与配置" class="nav-group"><button class="nav-link ${view==='knowledge'?'active':''}" data-view="knowledge">${icon('book')}制度知识库</button><button class="nav-link ${view==='settings'?'active':''}" data-view="settings">${icon('settings')}连接与设置</button></nav><div class="sidebar-bottom"><div class="connection-note"><strong><i class="dot"></i>交互演示空间</strong>上传与操作保存在本浏览器<br>WorkBuddy 尚未连接</div><div class="profile"><span class="avatar">${role==='finance'?'财':'林'}</span><span class="profile-text">${role==='finance'?'财务管理员':'林悦'}<small>${role==='finance'?'管理视图 · 示例角色':'员工视图 · 示例角色'}</small></span>${icon('down')}</div></div>`;
 const labels={overview:'工作台总览',expenses:'报销预审',invoices:'发票中心',logs:'咨询日志',insights:'问题洞察',knowledge:'制度知识库',settings:'连接与设置',employee:'我的工作台',consult:'报销咨询',new:'发起报销',mine:'我的报销',submitted:'提交结果',report:'报销报告'};
 document.getElementById('topbar').innerHTML=`<div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span>${role==='finance'?'财务管理':'员工服务'}</span><span class="slash">/</span><strong>${labels[view]||'工作台'}</strong></div><div class="top-actions"><span class="demo-tag">DEMO · 演示版</span><button class="btn" data-action="switch-role">${icon(role==='finance'?'user':'dashboard')}${role==='finance'?'员工入口':'返回财务后台'}${icon('arrow')}</button><span class="avatar">${role==='finance'?'财':'林'}</span></div>`;
 if(!document.querySelector('.menu-scrim')){const b=document.createElement('button');b.className='menu-scrim';b.ariaLabel='关闭导航';b.dataset.action='close-menu';document.body.append(b);}
}
function navigate(next){if(view==='new'&&next!=='submitted')rememberForm();view=next;currentPage=1;searchQuery='';statusFilter='all';shell();render();document.getElementById('sidebar').classList.remove('open');document.querySelector('.menu-scrim')?.classList.remove('open');window.scrollTo({top:0});}
function render(){const main=document.getElementById('main');const pages={overview:overviewPage,expenses:expensesPage,invoices:invoicesPage,logs:logsPage,insights:insightsPage,knowledge:knowledgePage,settings:settingsPage,employee:employeePage,consult:consultPage,new:newPage,mine:expensesPage,submitted:submittedPage,report:reportPage};main.innerHTML=(pages[view]||overviewPage)();if(storageWarning)main.insertAdjacentHTML('afterbegin','<div class="notice warning">浏览器存储不可用或已满。请导出需要保留的数据。</div>');if(view==='new')restoreForm();bindPage();}
function kpis(rows){const logs=selectedLogs(),pending=rows.filter(r=>r.status==='pending'),resolved=logs.filter(r=>r.resolved).length;return`<div class="stats-row"><section class="stat"><div class="stat-top">报销总金额${icon('receipt')}</div><div class="stat-value num"><span class="currency">¥</span>${moneyShort(sum(rows))}</div><div class="stat-foot"><b>${rows.length} 笔申请</b><span>所选期间累计</span></div></section><section class="stat"><div class="stat-top">待审核报销${icon('clock')}</div><div class="stat-value num">${pending.length}<span class="unit">笔</span></div><div class="stat-foot"><b class="warn">${pending.filter(r=>r.issue).length} 笔待核对</b><span>需要财务关注</span></div></section><section class="stat"><div class="stat-top">预审无异常${icon('shield')}</div><div class="stat-value num">${rows.length?Math.round(rows.filter(r=>!r.issue).length/rows.length*100):0}<span class="unit">%</span></div><div class="stat-foot"><b>${rows.filter(r=>!r.issue).length} 笔</b><span>仍需人工复核</span></div></section><section class="stat"><div class="stat-top">报销咨询${icon('chat')}</div><div class="stat-value num">${logs.length}<span class="unit">次</span></div><div class="stat-foot"><b>${resolved} 次匹配指引</b><span>示例日志统计</span></div></section></div>`;}
function trend(rows){const buckets=period==='quarter'?['8 月','9 月','10 月']:['01–04','05–08','09–12','13–16','17–20','21–末'];const totals=buckets.map(()=>0),paid=buckets.map(()=>0);rows.forEach(r=>{const i=period==='quarter'?Number(r.date.slice(5,7))-8:Math.min(5,Math.floor((Number(r.date.slice(8,10))-1)/4));if(i>=0&&i<totals.length){totals[i]+=r.amount;if(r.status==='paid'||r.status==='approved')paid[i]+=r.amount;}});const max=Math.max(...totals,10000),top=Math.ceil(max/10000)*10000;const w=600,h=177,left=51,right=18,bottom=152;const x=i=>left+(w-left-right)*i/(buckets.length-1);const y=v=>bottom-(v/top)*124;const path=arr=>arr.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');return`<svg class="trend-chart" viewBox="0 0 600 182" role="img" aria-label="报销金额趋势，实线为申请金额，浅色线为已审核金额">${[0,1,2,3].map(i=>{const yy=bottom-i*124/3;return`<line x1="${left}" y1="${yy}" x2="582" y2="${yy}" stroke="#edf1e8" stroke-dasharray="3 4"/><text x="7" y="${yy+4}">${(top*i/3/10000).toFixed(1)} 万</text>`;}).join('')}<path d="${path(totals)} L582,${bottom} L${left},${bottom}Z" fill="#eff5e7"/><path d="${path(paid)}" fill="none" stroke="#bdcfad" stroke-width="2.2" stroke-dasharray="5 4"/><path d="${path(totals)}" fill="none" stroke="#3e7757" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>${totals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.6" fill="#fff" stroke="#3e7757" stroke-width="2"><title>${buckets[i]}：申请 ¥${money(v)}，已审核 ¥${money(paid[i])}</title></circle>`).join('')}${buckets.map((v,i)=>`<text x="${x(i)}" y="176" text-anchor="middle">${v}</text>`).join('')}</svg>`;}
function categories(rows){const total=sum(rows),values=cats.map(c=>sum(rows.filter(r=>r.category===c)));let offset=0;const arcs=values.map((v,i)=>{const percent=total?v/total*100:0;const arc=`<circle cx="80" cy="80" r="62" fill="none" stroke="${colors[i]}" stroke-width="16" pathLength="100" stroke-dasharray="${Math.max(0,percent-.8)} ${100-Math.max(0,percent-.8)}" stroke-dashoffset="${-offset}"><title>${cats[i]} ¥${money(v)}</title></circle>`;offset+=percent;return arc;});return`<div class="category-content"><div class="donut-wrap"><svg viewBox="0 0 160 160" role="img" aria-label="各类报销费用占比"><circle cx="80" cy="80" r="62" fill="none" stroke="#f0f3eb" stroke-width="16"/>${arcs.join('')}</svg><div class="donut-center"><span>费用类型</span><strong>${values.filter(v=>v>0).length}</strong><span>类支出</span></div></div><div class="category-legend">${cats.map((c,i)=>`<div class="category-line"><i class="color-dot" style="background:${colors[i]}"></i><span>${c}</span><strong class="num">${total?Math.round(values[i]/total*100):0}%</strong></div>`).join('')}</div></div><div class="category-note">按报销金额统计 · 点击「查看明细」查看原始记录</div>`;}
function rankedTopics(){const logs=selectedLogs();const counts={};logs.forEach(l=>counts[l.topic]=(counts[l.topic]||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1]);}
function hotList(){const ranked=rankedTopics();if(!ranked.length)return'<div class="empty"><h3>所选期间暂无咨询</h3><p>员工提问后会显示问题分布。</p></div>';return`<div class="hot-list">${ranked.slice(0,4).map(([t,n],i)=>`<div class="hot-item"><div class="hot-top"><span class="hot-rank">${String(i+1).padStart(2,'0')}</span><strong>${esc(t)}</strong><span class="num">${n} 次</span></div><div class="bar-track"><div class="bar-fill" style="width:${n/ranked[0][1]*100}%;background:${i===0?'#3c7755':i===1?'#80a17a':'#b3c8a2'}"></div></div></div>`).join('')}</div>`;}
function overviewPage(){const rows=selectedRows(),pending=rows.filter(r=>r.status==='pending'),returned=rows.filter(r=>r.status==='returned'),ready=rows.filter(r=>r.status==='approved'),top=rankedTopics()[0];return heading('让每一笔报销，都有据可循。','2026 年 10 月 22 日，星期四 · 这是你的财务工作台',filters()+`<button class="btn" data-action="export-csv">${icon('download')}导出报表</button>`)+kpis(rows)+`<div class="wide-grid"><section class="pending-panel"><div class="pending-head"><h2>${icon('folder')}今日待办</h2><span>所选范围内的处理队列</span></div><div class="queue-grid"><div class="queue"><strong class="num">${pending.length}</strong><span>报销待审核</span><button class="queue-action" data-queue="pending">去审核${icon('arrow')}</button></div><div class="queue"><strong class="num">${returned.length}</strong><span>退回待补充</span><button class="queue-action" data-queue="returned">查看进度${icon('arrow')}</button></div><div class="queue"><strong class="num">${ready.length}</strong><span>审核后待支付</span><button class="queue-action" data-queue="approved">查看明细${icon('arrow')}</button></div></div></section><section class="insight-panel"><div class="insight-head">${icon('spark')}本期问题提示</div><p>${top?`「${esc(top[0])}」被咨询 <b>${top[1]} 次</b>，<br>建议纳入下一次员工报销培训。`:'所选范围暂无咨询记录，<br>试试从员工入口发起一次咨询。'}</p><button data-view="insights">查看问题分析与培训建议${icon('arrow')}</button></section></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>报销金额趋势</h2><p>按费用发生日期汇总 · 单位：元</p></div><div class="legend"><span><i></i>申请金额</span><span><i class="soft"></i>已审核</span></div></div>${trend(rows)}<div class="chart-foot"><span>本期已审核 <b>¥ ${money(sum(rows.filter(r=>['paid','approved'].includes(r.status))))}</b></span><span>示例数据，随筛选联动</span></div></section><section class="panel"><div class="panel-head"><h2>费用构成</h2><button class="btn subtle" data-view="expenses">查看明细${icon('arrow')}</button></div>${categories(rows)}</section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>最近报销</h2><button class="btn subtle" data-view="expenses">全部报销${icon('arrow')}</button></div><div class="table-toolbar"><div class="tabs"><button class="tab ${statusFilter==='all'?'active':''}" data-status="all">全部申请</button><button class="tab ${statusFilter==='pending'?'active':''}" data-status="pending">待审核<span>${pending.length}</span></button><button class="tab ${statusFilter==='returned'?'active':''}" data-status="returned">已退回</button></div><div class="small muted">最新 5 笔</div></div>${expenseTable(rows.filter(r=>statusFilter==='all'||r.status===statusFilter).slice(0,5),true)}<div class="table-bottom"><span>共 ${rows.length} 笔申请 · 演示记录</span><button class="table-action" data-view="expenses">查看所有记录 →</button></div></section><section class="panel"><div class="panel-head"><h2>高频咨询问题</h2><span class="small muted">${selectedLogs().length} 次咨询</span></div>${hotList()}<div class="hot-foot">将反复出现的问题，变成员工看得懂的指引。</div></section></div>`;}
function expenseTable(rows,compact=false){if(!rows.length)return`<div class="empty">${icon('search')}<h3>没有匹配的报销记录</h3><p>换一个时间、部门或搜索词试试。</p></div>`;return`<div class="table-wrap"><table><thead><tr><th>报销事项</th><th>申请人</th>${!compact?'<th>费用类型</th><th>发生日期</th>':''}<th>金额</th><th>状态</th>${!compact?'<th>预审提示</th>':''}<th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="cell-title">${esc(r.title)}</span><span class="cell-sub">${esc(r.id)}</span></td><td><div class="person-cell"><span class="avatar">${esc(r.person[0])}</span><span>${esc(r.person)}${!compact?`<span class="cell-sub">${esc(r.dept)}</span>`:''}</span></div></td>${!compact?`<td>${esc(r.category)}</td><td class="num">${esc(r.date)}</td>`:''}<td class="money num">¥ ${money(r.amount)}</td><td>${statusBadge(r.status)}</td>${!compact?`<td><span class="badge ${r.issue?'warn':''}">${esc(r.issue||'未发现字段异常')}</span></td>`:''}<td><button class="table-action" data-detail="${r.id}">${role==='finance'&&r.status==='pending'?'审核':'查看'}</button></td></tr>`).join('')}</tbody></table></div>`;}
function filteredExpenses(){return selectedRows({mine:view==='mine'}).filter(r=>(statusFilter==='all'||r.status===statusFilter)&&(!searchQuery||[r.title,r.id,r.person,r.dept].some(v=>v.toLowerCase().includes(searchQuery.toLowerCase()))));}
function expensesPage(){const mine=view==='mine',all=selectedRows({mine}),rows=filteredExpenses();return heading(mine?'我的报销':'报销预审',mine?'查看申请进度、退回原因与报销报告。':'先核对异常，再完成复核。每次操作都会留在报销日志里。',filters()+`<button class="btn ${mine?'primary':''}" data-action="${mine?'new-expense':'export-csv'}">${icon(mine?'plus':'download')}${mine?'发起报销':'导出明细'}</button>`)+`<section class="panel full-panel"><div class="table-toolbar"><div class="tabs">${[['all','全部'],['pending','待审核'],['returned','已退回'],['approved','待支付'],['paid','已支付']].map(([s,l])=>`<button class="tab ${statusFilter===s?'active':''}" data-status="${s}">${l}<span>${all.filter(r=>s==='all'||r.status===s).length}</span></button>`).join('')}</div></div><div class="filter-line"><div class="search">${icon('search')}<input id="expense-search" aria-label="搜索报销" placeholder="搜索报销事项、单号或申请人" value="${esc(searchQuery)}"></div><span class="filter-label">${mine?'当前示例员工：林悦':'规则预审仅供参考，最终由财务复核'}</span></div><div id="expense-results">${expenseResults(rows)}</div></section>`;}
function expenseResults(rows){const pages=Math.max(1,Math.ceil(rows.length/8));currentPage=Math.min(currentPage,pages);return expenseTable(rows.slice((currentPage-1)*8,currentPage*8))+`<div class="table-bottom"><span>共 ${rows.length} 笔 · 第 ${currentPage} / ${pages} 页</span><div class="pagination"><button data-page="${currentPage-1}" ${currentPage===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:pages},(_,i)=>`<button class="${currentPage===i+1?'active':''}" data-page="${i+1}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}<button data-page="${currentPage+1}" ${currentPage===pages?'disabled':''} aria-label="下一页">›</button></div></div>`;}
function employeePage(){const rows=state.expenses.filter(r=>r.mine),pending=rows.filter(r=>r.status==='pending').length,returned=rows.filter(r=>r.status==='returned').length;return`<section class="employee-welcome"><div><h1>林悦，你好。<br>把报销的事，简单一点。</h1><p>报销前先问清楚，提交时少走弯路。</p></div><button class="btn" data-view="new">${icon('plus')}发起一笔报销</button></section><div class="service-actions"><button class="service-action" data-view="consult">${icon('chat')}<div><h3>报销前，问一问</h3><p>查标准、问材料、了解流程</p></div><span class="arrow">${icon('arrow')}</span></button><button class="service-action" data-view="new">${icon('upload')}<div><h3>上传凭证，填报销</h3><p>核对信息，完成提交</p></div><span class="arrow">${icon('arrow')}</span></button><button class="service-action" data-view="mine">${icon('clock')}<div><h3>查看我的进度</h3><p>${pending} 笔待审核 · ${returned} 笔待补充</p></div><span class="arrow">${icon('arrow')}</span></button></div><div class="notice">${icon('shield')}这是本地演示入口。当前身份为示例员工，角色切换不代表真实权限校验，请使用测试资料体验。</div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>我的近期报销</h2><button class="btn subtle" data-view="mine">查看全部${icon('arrow')}</button></div><div style="height:15px"></div>${expenseTable(rows.slice(0,5),true)}</section><section class="panel"><div class="panel-head"><h2>报销前准备好这三件事</h2></div><div class="check-list">${[['book','确认适用制度','核对出差、招待等费用的标准及审批要求。'],['invoice','保留完整凭证','发票、支付凭证与行程信息保持对应。'],['checkCircle','说明业务事由','明确时间、地点、项目和费用用途。']].map(([ic,t,p])=>`<div class="check-row">${icon(ic)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section></div>`;}
function consultPage(){
 const count=DEMO_KNOWLEDGE.docs.reduce((n,d)=>n+d.clauses.length,0);
 const questions=['我去深圳出差，住宿费用多少？','深圳酒店600元一晚能报吗？','出差3天，提供了午餐，餐补多少？','报销8000元需要谁审批？','高铁一等座可以报销吗？','发票抬头和税号是什么？'];
 return heading('报销咨询','按制度给答案，按条款看依据。')+`<div class="knowledge-notice">${icon('book')}<span><strong>${esc(DEMO_KNOWLEDGE.company)} · 虚构企业知识库</strong>已载入 ${DEMO_KNOWLEDGE.docs.length} 份制度、${count} 条条款，所有标准仅用于演示。</span><button class="btn subtle" data-view="knowledge">查看知识库${icon('arrow')}</button></div><div class="content-grid"><section class="panel chat-shell"><div class="chat-header"><span class="bot-avatar">${icon('bot')}</span><div><h2>财务小助手</h2><p>本地知识检索与规则计算 · 可查看原文出处</p></div></div><div class="chat-context"><label for="chat-role">你的职级</label><select id="chat-role">${DEMO_KNOWLEDGE.roles.map(r=>`<option ${chatContext.role===r?'selected':''}>${r}</option>`).join('')}</select><span id="chat-context-city">${chatContext.city?'当前城市：'+esc(chatContext.city):'在问题里告诉我出差城市'}</span><button class="link-button" data-action="reset-chat-context">重置条件</button></div><div id="chat-messages" class="chat-messages">${chatHTML()}</div><div class="suggestions">${['我去深圳出差，住宿费用多少？','那部门经理呢？','住三晚呢？'].map(q=>`<button class="suggestion" data-question="${q}">${q}</button>`).join('')}</div><div class="chat-input"><form id="chat-form"><input id="chat-text" aria-label="输入报销问题" placeholder="试试：深圳酒店600元一晚能报吗？" maxlength="500" required><button class="btn primary" type="submit">发送${icon('arrow')}</button></form><p>回答来自虚构制度和本地规则，未连接外部 AI；不构成真实审批结果。</p></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>直接试问一句</h2></div><div class="topic-list">${questions.map((q,i)=>`<button class="topic-item" data-question="${q}">${q}<small>${['查城市与职级对应的具体额度','计算超标金额与例外审批','计算补贴及已提供餐食的扣减','按金额匹配完整审批链','区分员工与高管交通标准','查看可用的虚构开票信息'][i]}</small></button>`).join('')}</div></section><section class="panel lodging-quick"><div class="panel-head"><h2>住宿标准速查</h2><span class="badge">虚构标准</span></div><div class="table-wrap"><table><thead><tr><th>城市类别</th>${DEMO_KNOWLEDGE.roles.map(r=>`<th>${esc(r)}</th>`).join('')}</tr></thead><tbody>${DEMO_KNOWLEDGE.lodgingTiers.map(t=>`<tr><td>${esc(t.name)}</td>${t.rates.map(rate=>`<td>¥ ${rate}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>含税 / 间·晚 · 凭票按实际费用报销<br>北京、上海、广州、深圳适用一线城市标准</p><button class="table-action" data-doc="kb-travel">查看城市清单和例外条款 →</button></section></div></div>`;
}

function chatHTML(){return`<div class="message"><span class="bot-avatar">${icon('bot')}</span><div class="bubble">你好，星澜能源的虚构报销制度已经准备好了。\n可以直接问我城市住宿额度、餐补、交通标准、报销时限或审批流程，也可以连续追问。\n\n例如：「我去深圳出差，住宿费用多少？」<span class="source-tag">默认按普通员工回答，可在上方切换职级。</span></div></div>`+chatMessages.map(m=>`<div class="message ${m.user?'user':''}">${m.user?'':`<span class="bot-avatar">${icon('bot')}</span>`}<div class="bubble">${esc(m.text)}${m.citations?.length?`<div class="source-tag citation-list"><span>依据 · 点击查看原文</span>${m.citations.map(c=>`<button class="citation" data-cite-doc="${esc(c.docId)}" data-cite-clause="${esc(c.clauseId)}">${icon('book')}${esc(c.clauseId)} · ${esc(c.title)}${icon('arrow')}</button>`).join('')}</div>`:m.source?`<span class="source-tag">${esc(m.source)}</span>`:''}</div></div>`).join('');}

function askQuestion(q){q=q.trim();if(!q)return;const a=policyAnswer(q,chatContext);chatContext={...chatContext,...a.context};chatMessages.push({user:true,text:q},{user:false,text:a.text,source:a.source,citations:a.citations});state.logs.unshift({id:'QA'+Date.now(),person:'林悦',dept:'运营管理部',question:q,topic:a.topic,date:stamp().slice(0,10),resolved:a.resolved,answer:a.text,source:a.source,citations:a.citations,sample:false,context:{...chatContext},knowledgeVersion:DEMO_KNOWLEDGE.version});persist();document.getElementById('chat-messages').innerHTML=chatHTML();document.getElementById('chat-text').value='';document.getElementById('chat-role').value=chatContext.role;document.getElementById('chat-context-city').textContent=chatContext.city?'当前城市：'+chatContext.city:'在问题里告诉我出差城市';const box=document.getElementById('chat-messages');box.scrollTop=box.scrollHeight;}

function fileChips(files){return files.map((f,i)=>`<div class="file-chip">${icon('invoice')}<span>${esc(f.name)}</span><small>${Math.max(1,Math.round(f.size/1024))} KB</small><button class="icon-btn" type="button" data-remove-file="${i}" aria-label="移除 ${esc(f.name)}">${icon('close')}</button></div>`).join('');}
function newPage(){return heading(revisionId?'补正报销':'发起报销',revisionId?'修改原申请并重新提交，单号与处理历史将保留。':'填写费用信息，上传凭证，核对预审提示后提交。')+(revisionId?`<div class="notice warning"><div><strong>正在补正原单 ${esc(revisionId)}</strong><p>本次提交将更新原申请。取消补正会清空未提交的修改，保留原退回记录。</p><button class="btn" data-action="cancel-revision">取消补正，另开新单</button></div></div>`:'')+`<div class="steps"><div class="step active"><b>1</b>填写信息</div><div class="step"><b>2</b>核对预审</div><div class="step"><b>3</b>提交报销</div></div><div class="content-grid"><section class="panel form-panel"><h2>这笔费用，用在了哪里？</h2><p>${revisionId?'请按退回意见补充材料与说明，带 * 的项目为必填。':'带 * 的项目为必填。可先载入一份示例体验流程。'}</p><form id="expense-form"><div class="form-grid"><div class="field full"><label for="f-title">报销事项 <span class="required">*</span></label><input id="f-title" name="title" placeholder="例如：郑州项目调研差旅费用" maxlength="80" required></div><div class="field"><label for="f-dept">所属部门 <span class="required">*</span></label><select id="f-dept" name="dept">${depts.map(d=>`<option>${d}</option>`).join('')}</select></div><div class="field"><label for="f-category">费用类型 <span class="required">*</span></label><select id="f-category" name="category">${cats.map(d=>`<option>${d}</option>`).join('')}</select></div><div class="field"><label for="f-amount">报销金额（元） <span class="required">*</span></label><input id="f-amount" name="amount" type="number" min="0.01" max="99999999" step="0.01" placeholder="0.00" required></div><div class="field"><label for="f-date">费用发生日期 <span class="required">*</span></label><input id="f-date" name="date" type="date" value="2026-10-22" max="${stamp().slice(0,10)}" required></div><div class="field"><label for="f-invoice">发票号码</label><input id="f-invoice" name="invoiceNo" inputmode="numeric" maxlength="30" placeholder="请核对票面后填写"></div><div class="field"><label for="f-company">购买方抬头</label><input id="f-company" name="company" maxlength="100" placeholder="填写企业正式开票抬头"></div><div class="field full"><label for="f-note">费用用途 <span class="required">*</span></label><textarea id="f-note" name="note" rows="3" maxlength="1000" placeholder="说明项目、出差地点、时间与业务事由" required></textarea></div><div class="field full"><label>上传发票与附件</label><label class="dropzone">${icon('upload')}<strong>点击选择，或拖入凭证文件</strong><p>PDF、JPG、PNG、WebP · 每个不超过 10 MB · 最多 8 个</p><input id="expense-files" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" multiple aria-label="上传报销凭证"></label><div id="expense-file-list" class="file-list">${fileChips(newFiles)}</div><span class="receipt-warning">未启用 OCR：上传后请手动填写并核对票面字段。</span></div></div><div id="precheck-result"></div><div class="form-actions">${revisionId?'':'<button type="button" class="btn" data-action="sample-expense">载入示例</button>'}<button type="button" class="btn" data-action="save-draft">保存草稿</button><button class="btn primary" type="submit">核对并提交${icon('arrow')}</button></div></form></section><div class="stack"><section class="panel"><div class="panel-head"><h2>提交前，系统会检查</h2></div><div class="check-list">${[['checkCircle','基础信息完整','检查报销金额、日期与用途是否填写。'],['invoice','重复发票号','与当前演示空间已有报销记录比对。'],['folder','凭证是否齐全','提示缺失附件、发票号或购买方信息。'],['user','最终由财务复核','规则预审不代表合规认定或审批通过。']].map(([ic,t,p])=>`<div class="check-row">${icon(ic)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><div class="notice">${icon('shield')}附件只保存在当前浏览器，不上传到外部服务。换设备或清除浏览器数据后无法继续访问。</div><button class="btn" data-view="consult">${icon('chat')}不确定怎么填？先问一问</button></div></div>`;}
function rememberForm(){const form=document.getElementById('expense-form');if(form)formMemory=Object.fromEntries(new FormData(form));}
function restoreForm(){Object.entries(formMemory).forEach(([k,v])=>{const input=document.getElementById('expense-form').elements.namedItem(k);if(input)input.value=v;});document.getElementById('expense-file-list').innerHTML=fileChips(newFiles);}
function collectExpense(){const f=document.getElementById('expense-form');if(!f.reportValidity())return null;const vals=Object.fromEntries(new FormData(f));return {...vals,amount:Number(vals.amount)};}
function precheck(v,files,excludedId=revisionId){const issues=[];if(state.expenses.some(r=>r.id!==excludedId&&r.invoiceNo&&r.invoiceNo===v.invoiceNo))issues.push('发票号码重复：请核对已有记录');if(!files.length)issues.push('缺少发票或附件');if(!v.invoiceNo)issues.push('未填写发票号码');if(!v.company)issues.push('未填写购买方抬头');return issues;}
function showSubmitReview(){const v=collectExpense();if(!v)return;rememberForm();const issues=precheck(v,newFiles);const dialog=document.getElementById('detail');dialog.innerHTML=`<div class="detail-head"><div><h2 id="detail-title">核对预审结果</h2><p>确认信息后将进入财务待审核队列</p></div><button class="icon-btn" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="detail-body"><div class="detail-total"><p>${esc(v.title)}</p><strong>¥ ${money(v.amount)}</strong><span class="badge ${issues.length?'warn':''}">${issues.length?'发现 '+issues.length+' 项待核对':'基础字段检查通过'}</span></div><div class="notice ${issues.length?'warning':''}">${icon(issues.length?'warn':'checkCircle')}${issues.length?'你可以返回补充，也可以保留提示提交财务人工复核。':'仅完成资料与重复号检查，不代表票据验真或审批通过。'}</div>${issues.map(t=>`<div class="review-line warn">${icon('warn')}${esc(t)}</div>`).join('')}<dl class="detail-fields"><div><dt>费用类型</dt><dd>${esc(v.category)}</dd></div><div><dt>发生日期</dt><dd>${esc(v.date)}</dd></div><div><dt>所属部门</dt><dd>${esc(v.dept)}</dd></div><div><dt>凭证附件</dt><dd>${newFiles.length} 份</dd></div></dl><p class="small muted">${esc(v.note)}</p></div><div class="detail-actions"><button class="btn" data-action="close-dialog">返回修改</button><button class="btn primary" data-action="confirm-submit">确认提交（演示）</button></div>`;dialog.showModal();}
function submitExpense(){const v=collectExpense();if(!v)return;const original=revisionId?state.expenses.find(r=>r.id===revisionId):null;if(revisionId&&(!original||original.status!=='returned'||!original.mine)){toast('原申请已不处于可补正状态，请取消补正后重新核对。');return;}const issues=precheck(v,newFiles);const history=[{text:original?'员工补正后重新提交（保留原单号）':'员工提交报销申请',date:stamp()},{text:issues.length?'规则预审发现待核对项：'+issues.join('；'):'规则预审完成，等待财务复核',date:stamp()}];let record;if(original){record=original;Object.assign(record,v,{status:'pending',issue:issues.join('；'),files:[...newFiles],history:[...original.history,...history]});}else{record={...v,id:'BX'+Date.now(),person:'林悦',status:'pending',issue:issues.join('；'),files:[...newFiles],mine:true,history};state.expenses.unshift(record);}state.draft=null;lastSubmitted=record.id;revisionId=null;newFiles=[];formMemory={};persist();document.getElementById('detail').close();navigate('submitted');toast(original?'原报销单已补正重提，单号与处理历史已保留':'报销已提交到本地演示待审队列');}
function submittedPage(){const r=state.expenses.find(r=>r.id===lastSubmitted);if(!r)return employeePage();return heading('报销已提交','下一步由财务复核，你可以随时查看处理进度。')+`<section class="panel report-ready">${icon('checkCircle')}<h2>材料整理好了，交给财务吧。</h2><p>${esc(r.title)} · ¥ ${money(r.amount)}</p><p>申请编号：${r.id}</p><div class="heading-actions"><button class="btn primary" data-report="${r.id}">${icon('download')}下载报销报告</button><button class="btn" data-detail="${r.id}">查看申请详情</button><button class="btn" data-view="mine">我的报销</button></div></section><div class="notice" style="margin-top:22px">${icon('clock')}当前为演示提交。点击右上角「返回财务后台」即可查看并模拟审核这笔申请。</div>`;}
function invoicesPage(){const receipts=state.receipts;return heading('发票中心','统一整理凭证，手动核对票面信息，保留每一份报销依据。',`<button class="btn" data-view="new">${icon('plus')}发起报销</button>`)+`<div class="notice warning">${icon('invoice')}发票识别尚未接入。当前支持本地上传、预览和信息登记，不自动识别、不验真。</div><div class="content-grid"><section class="panel form-panel"><h2>上传并登记发票</h2><p>文件留在当前浏览器，字段由你核对后录入。</p><form id="receipt-form"><div class="form-grid"><div class="field full"><label class="dropzone">${icon('upload')}<strong>选择发票文件</strong><p>PDF、JPG、PNG、WebP · 单个不超过 10 MB</p><input id="receipt-file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" aria-label="选择发票文件" required></label><div id="receipt-file-label" class="file-list"></div></div><div class="field"><label for="r-number">发票号码 *</label><input id="r-number" name="invoiceNo" maxlength="30" required></div><div class="field"><label for="r-amount">价税合计（元） *</label><input id="r-amount" name="amount" type="number" min="0.01" max="99999999" step="0.01" required></div><div class="field full"><label for="r-company">购买方抬头 *</label><input id="r-company" name="company" maxlength="100" required></div></div><div class="form-actions"><button class="btn primary" id="save-receipt" type="submit">保存登记${icon('check')}</button></div></form></section><section class="panel"><div class="panel-head"><div><h2>已登记凭证</h2><p>${receipts.length} 份本地文件</p></div></div>${receipts.length?`<div class="topic-list">${receipts.map(r=>`<div class="topic-item"><div class="hot-top"><strong>${esc(r.file.name)}</strong><span class="badge">手工已核对</span></div><small>${esc(r.invoiceNo)} · ¥ ${money(r.amount)}</small><small>${esc(r.company)}</small><button class="table-action" data-file="${r.file.id}">打开凭证 →</button></div>`).join('')}</div>`:`<div class="empty">${icon('folder')}<h3>还没有登记的发票</h3><p>上传一份测试凭证，核对字段后保存。</p></div>`}</section></div>`;}
function logsPage(){const rows=selectedLogs().filter(l=>!searchQuery||[l.question,l.person,l.topic].some(v=>v.includes(searchQuery)));return heading('咨询日志','每一次提问都有记录，让员工遇到的难题被看见。',filters()+`<button class="btn" data-action="export-logs">${icon('download')}导出日志</button>`)+`<section class="panel"><div class="filter-line"><div class="search">${icon('search')}<input id="log-search" aria-label="搜索咨询日志" placeholder="搜索问题、员工或主题" value="${esc(searchQuery)}"></div><span class="small muted">${rows.filter(r=>!r.resolved).length} 条待人工答复</span></div><div id="log-results">${logTable(rows)}</div></section>`;}
function logTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>员工问题</th><th>咨询人</th><th>问题分类</th><th>日期</th><th>处理状态</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="cell-title">${esc(r.question)}</span><span class="cell-sub">${r.id}${r.sample?' · 示例日志':''}</span></td><td>${esc(r.person)}<span class="cell-sub">${esc(r.dept)}</span></td><td>${esc(r.topic)}</td><td>${esc(r.date)}</td><td><span class="badge ${r.resolved?'':'warn'}">${r.resolved?'已提供指引':'待人工答复'}</span></td><td><button class="table-action" data-log="${r.id}">查看</button></td></tr>`).join('')}</tbody></table></div><div class="table-bottom">共 ${rows.length} 条 · 全部日志可导出 CSV</div>`:'<div class="empty"><h3>没有匹配的咨询</h3><p>更换筛选条件，或从员工入口发起提问。</p></div>';}
function insightsPage(){const ranked=rankedTopics(),logs=selectedLogs(),top=ranked[0],open=logs.filter(l=>!l.resolved).length;return heading('把重复的问题，变成共同的知识。','从咨询记录中找到培训重点，减少下一次来回沟通。',filters()+`<button class="btn primary" data-action="training">${icon('download')}生成培训提纲</button>`)+`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>高频问题分布</h2><span class="small muted">按咨询次数排序</span></div><div class="report-summary"><div><span>咨询总量</span><strong>${logs.length} <small class="small muted">次</small></strong></div><div><span>问题主题</span><strong>${ranked.length} <small class="small muted">类</small></strong></div><div><span>待人工答复</span><strong>${open} <small class="small muted">条</small></strong></div></div>${hotList()}<div class="hot-foot">统计口径：所选期间和部门内，按问题主题统计咨询记录条数。</div></section><section class="insight-panel" style="padding:28px"><div class="insight-head">${icon('spark')}本期培训建议</div><p>${top?`优先讲清楚<br><b>「${esc(top[0])}」</b>`:'积累更多咨询后再确定培训重点'}</p><div style="font-size:12px;line-height:1.9;color:#d4dfcd;margin:12px 0 24px">${top?`这一主题占本期咨询的 ${Math.round(top[1]/logs.length*100)}%。建议结合一份完整报销案例，说明材料清单、常见错误与例外处理。`:'可以先用员工入口提问，系统会将新的问题记录进咨询日志。'}</div><button data-action="training">下载可编辑的培训提纲${icon('arrow')}</button></section></div><section class="panel full-panel" style="margin-top:22px"><div class="panel-head"><h2>从问题到改进</h2></div><div class="analysis-row"><div><h3>把规则说清楚</h3><p>为高频主题补一页「可以报什么、要带什么、特殊情况找谁」指引。用虚构制度中的明确额度与审批链演练；真实上线时替换为企业现行标准。</p><button class="table-action" data-view="knowledge">查看制度知识库 →</button></div><div><h3>把未解答的接住</h3><p>目前有 ${open} 条咨询待人工答复。财务补充答复后，可作为下一轮知识完善的材料。</p><button class="table-action" data-view="logs">查看咨询日志 →</button></div></div></section>`;}
function knowledgePage(){const count=DEMO_KNOWLEDGE.docs.reduce((n,d)=>n+d.clauses.length,0);return heading('制度知识库','完整虚构制度已就绪，可以查、可以问，也可以下载。',`<button class="btn" data-action="download-knowledge">${icon('download')}下载完整知识库</button><label class="btn primary" style="position:relative;overflow:hidden">${icon('upload')}上传制度<input id="knowledge-file" type="file" accept=".txt,.md,.pdf,.docx" style="position:absolute;inset:0;opacity:0;cursor:pointer" aria-label="上传制度文件"></label>`)+`<div class="knowledge-notice">${icon('book')}<span><strong>${esc(DEMO_KNOWLEDGE.company)} · V2.0</strong>${DEMO_KNOWLEDGE.docs.length} 份制度 · ${count} 条条款 · ${DEMO_KNOWLEDGE.docs.find(d=>d.id==='kb-cases')?.clauses.length||0} 个算例 · 2026-10-01 生效（虚构）</span><button class="btn subtle" data-action="open-consult">去试问${icon('arrow')}</button></div><div class="notice">${icon('shield')}这套标准由演示虚构，不代表中裕燃气或其他真实公司的规定。上传的 TXT / Markdown 可看全文；新文件尚未参与问答，PDF / Word 等待解析。</div><div class="panel knowledge-search-panel"><div class="search">${icon('search')}<input id="knowledge-search" aria-label="搜索制度条款" placeholder="搜索深圳、餐补、审批、发票，或条款编号 TR-02" value="${esc(knowledgeQuery)}"></div><span class="small muted">搜索覆盖完整条款正文</span></div><div id="knowledge-results">${knowledgeResults(knowledgeQuery)}</div>`;}
function knowledgeResults(query=''){
 const q=query.trim().toLowerCase();
 if(q){const matches=[];for(const d of state.docs){if(d.clauses){for(const c of d.clauses)if([d.title,c.id,c.title,c.body,...(c.tags||[])].join(' ').toLowerCase().includes(q))matches.push({doc:d,clause:c});}else if([d.title,d.content].join(' ').toLowerCase().includes(q))matches.push({doc:d});}
 return`<p class="knowledge-result-count">找到 ${matches.length} 条结果</p><div class="knowledge-result-list">${matches.map(({doc:d,clause:c})=>`<article class="panel knowledge-result"><span class="badge">${c?esc(c.id):'用户文档'}</span><h2><button class="link-button" ${c?`data-cite-doc="${esc(d.id)}" data-cite-clause="${esc(c.id)}"`:`data-doc="${esc(d.id)}"`}>${esc(c?c.title:d.title)}</button></h2><p>${esc((c?c.body:d.content||'').slice(0,230))}${(c?c.body:d.content||'').length>230?'…':''}</p><small>${esc(d.title)}</small></article>`).join('')||'<div class="empty"><h3>暂未找到对应条款</h3><p>试试“住宿”“审批”或条款编号。</p></div>'}</div>`;
 }
 return`<div class="knowledge-grid">${state.docs.map(d=>`<article class="panel doc-card"><div class="doc-top"><span class="doc-icon">${icon('book')}</span><span class="badge ${d.pending?'warn':''}">${d.pending?'待解析':d.builtin?'已用于问答':esc(d.type)}</span></div><h2>${esc(d.title)}</h2><p>${esc(d.summary||(d.pending?'原文件已保存在本浏览器，尚未提取正文。':'文件正文可查看；尚未用于智能问答检索。'))}</p><div class="doc-meta">${d.clauses?`${d.clauses.length} 条条款 · ${esc(d.version)}`:esc(d.size)}</div><div class="doc-bottom"><span>${esc(d.date)}</span><button class="table-action" data-doc="${esc(d.id)}">${d.pending?'下载原文':'查看全文'} →</button></div></article>`).join('')}</div>`;
}

function settingsPage(){return heading('连接与设置','明确当前能力，也为下一步接入企业系统留好位置。')+`<div class="notice warning">${icon('shield')}这是浏览器本地演示，没有登录鉴权、多人同步或真实付款功能。切换角色仅用于查看不同界面。</div><section class="panel"><div class="panel-head"><h2>企业服务连接</h2><span class="badge gray">尚未连接外部服务</span></div><div class="integration-list">${[['bot','WorkBuddy 智能体','需要确认企业可用的接入方式，再配置受保护的服务端调用。'],['invoice','发票 OCR 与验真','需要可用的识别/验真服务，当前由用户手动录入并核对。'],['book','企业制度检索','当前已提供完整虚构制度和条款引用；真实文件解析、权限化检索与模型服务待接入。'],['branch','OA / ERP 审批与付款','需要审批流、部门权限、员工身份与系统接口。']].map(([ic,t,p])=>`<div class="integration">${icon(ic)}<div><h3>${t}</h3><p>${p}</p></div><span class="badge gray">待接入</span></div>`).join('')}</div></section><section class="panel full-panel" style="margin-top:22px"><div class="panel-head"><h2>本地演示数据</h2></div><div class="analysis-row"><div><h3>下载结构化备份</h3><p>导出报销记录、咨询日志、制度正文和凭证登记信息。原始二进制附件需单独下载。</p><button class="btn" data-action="backup" style="margin-top:15px">${icon('download')}导出 JSON 备份</button></div><div><h3>需要正式上线时</h3><p>准备企业制度、开票信息、费用标准、审批权限、接入账户与部署环境。真实报销数据应放在有访问控制的服务端。</p><button class="table-action" data-action="implementation">下载接入清单 →</button></div></div></section>`;}
function reportPage(){const rows=selectedRows();return heading('报销汇总报告','当前筛选范围内的报销记录与处理状态。',filters()+`<button class="btn" data-action="export-csv">${icon('download')}导出 CSV</button><button class="btn primary" data-action="print">打印 / PDF</button>`)+kpis(rows)+`<section class="panel"><div class="panel-head"><h2>费用明细</h2></div><div style="height:16px"></div>${expenseTable(rows)}</section>`;}
function showDetail(id){const r=state.expenses.find(r=>r.id===id);if(!r)return;selectedId=id;const dialog=document.getElementById('detail');dialog.innerHTML=`<div class="detail-head"><div><h2 id="detail-title">报销详情</h2><p>${esc(r.id)}</p></div><button class="icon-btn" data-action="close-dialog" aria-label="关闭详情">${icon('close')}</button></div><div class="detail-body"><div class="detail-total"><p>${esc(r.title)}</p><strong class="num">¥ ${money(r.amount)}</strong>${statusBadge(r.status)}</div><dl class="detail-fields"><div><dt>申请人</dt><dd>${esc(r.person)}</dd></div><div><dt>所属部门</dt><dd>${esc(r.dept)}</dd></div><div><dt>费用类型</dt><dd>${esc(r.category)}</dd></div><div><dt>费用发生日期</dt><dd>${esc(r.date)}</dd></div><div><dt>发票号码</dt><dd>${esc(r.invoiceNo||'未填写')}</dd></div><div><dt>购买方抬头</dt><dd>${esc(r.company||'未填写')}</dd></div></dl><h3>费用说明</h3><p class="small muted" style="margin-top:9px;white-space:pre-wrap">${esc(r.note)}</p><section class="detail-section"><h3>规则预审</h3><div class="review-line">${icon('checkCircle')}金额、日期与事由已登记</div>${r.issue?`<div class="review-line warn">${icon('warn')}<span>${esc(r.issue)}</span></div>`:`<div class="review-line">${icon('checkCircle')}未发现字段异常，仍需核对原始凭证</div>`}<p class="small muted" style="margin-top:8px">未执行 OCR、税务验真、费用限额或企业制度匹配。</p></section><section class="detail-section"><h3>凭证附件 <span class="muted small">${r.files.length} 份</span></h3>${r.files.length?r.files.map(f=>`<div class="file-chip">${icon('invoice')}<span>${esc(f.name)}</span>${f.sample?'<small>示例占位</small>':`<button class="table-action" data-file="${f.id}">打开</button>`}</div>`).join(''):'<p class="small muted">未上传附件</p>'}</section><section class="detail-section"><h3>处理日志</h3><ol class="timeline">${r.history.map(h=>`<li>${esc(h.text)}<time>${esc(h.date)}</time></li>`).join('')}</ol></section></div><div id="reject-container"></div><div class="detail-actions"><button class="btn" data-report="${r.id}">${icon('download')}报告</button>${role==='finance'&&r.status==='pending'?'<button class="btn danger" data-action="show-reject">退回补充</button><button class="btn primary" data-action="approve">模拟审核通过</button>':''}${r.status==='returned'&&r.mine&&role==='employee'?'<button class="btn primary" data-action="revise">补充后重新提交</button>':''}</div>`;if(!dialog.open)dialog.showModal();}
function reviewExpense(action,reason=''){const r=state.expenses.find(r=>r.id===selectedId);if(!r||r.status!=='pending'||role!=='finance')return;r.status=action==='approve'?'approved':'returned';r.history.push({text:action==='approve'?'财务模拟审核通过，等待支付（未触发真实审批/付款）':'财务退回补充：'+reason,date:stamp()});persist();document.getElementById('detail').close();shell();render();toast(action==='approve'?'模拟审核通过，已更新为待支付':'已退回，补充原因已写入处理日志');}
function showLog(id){const l=state.logs.find(l=>l.id===id);if(!l)return;const dialog=document.getElementById('detail');dialog.innerHTML=`<div class="detail-head"><div><h2 id="detail-title">咨询详情</h2><p>${esc(l.person)} · ${esc(l.dept)} · ${esc(l.date)}</p></div><button class="icon-btn" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="detail-body"><h3>员工问题</h3><p style="margin-top:12px">${esc(l.question)}</p><section class="detail-section"><h3>提供的指引</h3><div class="doc-body">${esc(l.answer)}</div><p class="source-tag">${esc(l.source)}</p></section>${!l.resolved?`<section class="detail-section"><h3>补充人工答复</h3><form id="reply-form" data-log-id="${l.id}"><label class="field"><span>答复内容</span><textarea name="reply" rows="5" maxlength="2000" required placeholder="请依据正式制度填写答复，并注明出处。"></textarea></label><button class="btn primary" style="margin-top:15px">保存答复（演示）</button></form></section>`:'<p class="small muted" style="margin-top:25px">该条已提供指引，不代表实际审批结果。</p>'}</div>`;dialog.showModal();}
function showDoc(id,clauseId=''){const d=state.docs.find(d=>d.id===id);if(!d)return;if(d.pending){openFile(d.file.id);return;}const dialog=document.getElementById('detail');dialog.innerHTML=`<div class="detail-head"><div><h2 id="detail-title">${esc(d.title)}</h2><p>${esc(d.type)} · ${esc(d.version||'')} · ${esc(d.date)}</p></div><button class="icon-btn" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="detail-body">${d.builtin?`<div class="notice">${icon('book')}星澜能源虚构制度，仅用于体验；不代表真实企业规定。</div><p class="small muted">${esc(d.summary)}</p><nav class="clause-index" aria-label="文档条款目录">${d.clauses.map(c=>`<button data-jump-clause="${esc(c.id)}">${esc(c.id)} ${esc(c.title)}</button>`).join('')}</nav>${d.clauses.map(c=>`<section class="knowledge-clause ${clauseId===c.id?'highlight':''}" id="clause-${esc(c.id)}"><h3>${esc(c.id)} · ${esc(c.title)}</h3><div class="doc-body">${esc(c.body)}</div></section>`).join('')}`:`<div class="doc-body">${esc(d.content)}</div>`}</div><div class="detail-actions"><button class="btn" data-download-doc="${esc(d.id)}">${icon('download')}下载正文</button></div>`;if(!dialog.open)dialog.showModal();if(clauseId)document.getElementById('clause-'+clauseId)?.scrollIntoView({block:'center'});}

function download(name,content,type='text/plain;charset=utf-8'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function toCSV(rows){return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
function exportExpenses(){const rows=view==='expenses'||view==='mine'?filteredExpenses():selectedRows();const headings=['报销单号','事项','申请人','部门','费用类型','日期','金额(元)','状态','预审提示','发票号','用途'];download('报销明细_'+period+'.csv',toCSV([headings,...rows.map(r=>[r.id,r.title,r.person,r.dept,r.category,r.date,r.amount,({pending:'待审核',returned:'已退回',approved:'待支付',paid:'已支付'})[r.status],r.issue||'未发现字段异常',r.invoiceNo,r.note])]),'text/csv;charset=utf-8');toast('已导出当前筛选范围的 '+rows.length+' 笔明细');}
function exportLogs(){const rows=selectedLogs().filter(l=>!searchQuery||[l.question,l.person,l.topic].some(v=>v.includes(searchQuery)));download('报销咨询日志_'+period+'.csv',toCSV([['编号','咨询人','部门','日期','问题','主题','状态','答复','出处'],...rows.map(l=>[l.id,l.person,l.dept,l.date,l.question,l.topic,l.resolved?'已提供指引':'待人工答复',l.answer,l.source])]),'text/csv;charset=utf-8');toast('已导出 '+rows.length+' 条咨询日志');}
function downloadReport(id){const r=state.expenses.find(r=>r.id===id);if(!r)return;const status=({pending:'待审核',returned:'已退回',approved:'待支付',paid:'已支付'})[r.status];const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>报销报告 ${esc(r.id)}</title><style>body{font:14px/1.8 -apple-system,"PingFang SC",sans-serif;color:#233c33;max-width:820px;padding:45px 25px;margin:auto}h1{font-size:27px}h2{font-size:17px;border-bottom:1px solid #ddd;padding-bottom:10px;margin-top:30px}table{border-collapse:collapse;width:100%}td{padding:10px;border-bottom:1px solid #eee}td:first-child{width:130px;color:#647366}p{white-space:pre-wrap}.notice{background:#f1f5eb;padding:15px;font-size:12px}button{padding:9px 16px;border:0;background:#163e35;color:white;border-radius:6px;cursor:pointer}@media print{button{display:none}body{padding:0}}</style><h1>报销申请报告</h1><p>${esc(r.id)} · 生成时间 ${stamp()}</p><div class="notice">本报告来自交互演示空间，不是正式审批或付款凭证。金额、票据与制度适用性需人工复核。</div><h2>${esc(r.title)}</h2><table>${[['申请人',r.person],['部门',r.dept],['费用类型',r.category],['发生日期',r.date],['申请金额','¥ '+money(r.amount)],['当前状态',status],['发票号码',r.invoiceNo||'未填写'],['购买方抬头',r.company||'未填写'],['预审提示',r.issue||'未发现字段异常；不代表税务验真或审批通过']].map(([k,v])=>`<tr><td>${k}</td><td>${esc(v)}</td></tr>`).join('')}</table><h2>费用说明</h2><p>${esc(r.note)}</p><h2>附件清单</h2><ul>${r.files.map(f=>`<li>${esc(f.name)}${f.sample?'（示例占位）':''}</li>`).join('')||'<li>未上传附件</li>'}</ul><h2>处理日志</h2><ol>${r.history.map(h=>`<li>${esc(h.date)} · ${esc(h.text)}</li>`).join('')}</ol><button onclick="window.print()">打印 / 保存为 PDF</button></html>`;download('报销报告_'+r.id+'.html',html,'text/html;charset=utf-8');toast('已下载报销报告，可打开后打印为 PDF');}
function trainingContent(){const ranked=rankedTopics(),logs=selectedLogs();return `# 星澜能源员工报销培训提纲（虚构）\n\n${DEMO_KNOWLEDGE.disclaimer}\n制度版本：${DEMO_KNOWLEDGE.version}\n生成时间：${stamp()}\n统计期间：${period==='quarter'?'2026 年 8–10 月':period}\n部门：${department==='all'?'全部部门':department}\n数据范围：${logs.length} 条咨询记录。按主题频次归纳，并引用当前虚构制度。\n\n## 培训目标\n掌握费用额度、资料要求、例外流程和提交时限，减少反复补件。\n\n## 重点主题\n${ranked.map(([t,n],i)=>{const item=logs.find(l=>l.topic===t),q=item?.question||t;const a=item?.answer?{text:item.answer,source:item.source}:policyAnswer(q,item?.context||{});return `\n### ${i+1}. ${t}（${n} 次，${logs.length?Math.round(n/logs.length*100):0}%）\n常见提问：${q}\n\n${a.text}\n\n制度出处：${a.source}\n`;}).join('')}\n## 互动演练\n1. 普通员工去深圳住 2 晚，每晚 420 元：申请 840 元，住宿上限 900 元。\n2. 普通员工深圳住宿每晚 600 元：超标 150 元，超标比例 33.3%，按 TR-03 走事前例外审批。\n3. 出差 3 天、每天提供午餐：餐补 3 × (100 − 40) = 180 元。\n\n## 建议议程（30 分钟）\n5 分钟：事前申请；10 分钟：高频条款；10 分钟：案例演练；5 分钟：答疑与复盘。\n\n## 待人工答复\n${logs.filter(l=>!l.resolved).map(l=>'- '+l.question).join('\n')||'本期无待答复记录。'}\n\n完整制度可在知识库中下载。所有标准均为虚构，不可直接用于真实企业审批。\n`;}

async function addFiles(list,target){const arr=Array.from(list);const maxCount=target==='expense'?8:1;if(arr.length+(target==='expense'?newFiles.length:0)>maxCount){toast('最多选择 '+maxCount+' 个文件');return;}if(arr.some(f=>f.size>10*1024*1024||!(/\.(pdf|jpe?g|png|webp)$/i.test(f.name)))){toast('请上传 10 MB 以内的 PDF、JPG、PNG 或 WebP');return;}const input=document.getElementById(target==='expense'?'expense-files':'receipt-file');input.disabled=true;const submit=document.querySelector(target==='expense'?'#expense-form button[type="submit"]':'#save-receipt');submit.disabled=true;try{const stored=[];for(const f of arr)stored.push(await putFile(f));if(target==='expense'){newFiles.push(...stored);document.getElementById('expense-file-list').innerHTML=fileChips(newFiles);}else{invoiceFiles=stored;document.getElementById('receipt-file-label').innerHTML=stored.map(f=>`<div class="file-chip">${icon('invoice')}<span>${esc(f.name)}</span><small>已保存在本地</small></div>`).join('');}toast('凭证已保存，请手动核对票面字段');}catch{toast('本地文件保存失败，请检查浏览器存储权限后重试');input.value='';}finally{input.disabled=false;submit.disabled=false;}}
async function openFile(id){try{const file=await getFile(id);if(!file){toast('本浏览器未找到原文件，请重新上传');return;}download(file.name,file);toast('已下载原始凭证，可从下载列表打开');}catch{toast('读取文件失败，请检查浏览器存储权限');}}
async function uploadKnowledge(file){if(!file)return;if(file.size>10*1024*1024||!/\.(txt|md|pdf|docx)$/i.test(file.name)){toast('请上传 10 MB 以内的 TXT、MD、PDF 或 DOCX');return;}try{const meta=await putFile(file);const textable=/\.(txt|md)$/i.test(file.name);if(textable&&file.size>1024*1024){toast('文本制度请控制在 1 MB 内，较大文档请使用 PDF');return;}const content=textable?await file.text():'';state.docs.unshift({id:crypto.randomUUID(),title:file.name,type:'用户上传',date:stamp().slice(0,10),size:Math.max(1,Math.round(file.size/1024))+' KB',content,pending:!textable,file:meta});persist();render();toast(textable?'制度正文已保存，可查看全文':'原文件已保存，等待接入解析服务');}catch{toast('上传失败，请检查本地存储权限后重试');}}
function bindPage(){document.getElementById('chat-role')?.addEventListener('change',e=>{chatContext={...chatContext,role:e.target.value};});document.getElementById('knowledge-search')?.addEventListener('input',e=>{knowledgeQuery=e.target.value;document.getElementById('knowledge-results').innerHTML=knowledgeResults(knowledgeQuery);});document.getElementById('period-filter')?.addEventListener('change',e=>{period=e.target.value;currentPage=1;render();});document.getElementById('dept-filter')?.addEventListener('change',e=>{department=e.target.value;currentPage=1;render();});document.getElementById('expense-search')?.addEventListener('input',e=>{searchQuery=e.target.value;currentPage=1;document.getElementById('expense-results').innerHTML=expenseResults(filteredExpenses());});document.getElementById('log-search')?.addEventListener('input',e=>{searchQuery=e.target.value;document.getElementById('log-results').innerHTML=logTable(selectedLogs().filter(l=>[l.question,l.person,l.topic].some(v=>v.includes(searchQuery))));});document.getElementById('chat-form')?.addEventListener('submit',e=>{e.preventDefault();askQuestion(document.getElementById('chat-text').value);});document.getElementById('expense-form')?.addEventListener('submit',e=>{e.preventDefault();showSubmitReview();});document.getElementById('expense-files')?.addEventListener('change',e=>addFiles(e.target.files,'expense'));document.getElementById('receipt-file')?.addEventListener('change',e=>addFiles(e.target.files,'receipt'));document.getElementById('knowledge-file')?.addEventListener('change',e=>uploadKnowledge(e.target.files[0]));document.getElementById('receipt-form')?.addEventListener('submit',e=>{e.preventDefault();if(!invoiceFiles.length){toast('请先上传发票文件');return;}const v=Object.fromEntries(new FormData(e.target));if(state.receipts.some(r=>r.invoiceNo===v.invoiceNo)){toast('此发票号码已登记，请核对后再保存');return;}state.receipts.unshift({...v,id:crypto.randomUUID(),amount:Number(v.amount),file:invoiceFiles[0],date:stamp().slice(0,10)});invoiceFiles=[];persist();render();toast('发票信息已登记');});}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-view]');if(!b)return;
 if(b.dataset.citeDoc){showDoc(b.dataset.citeDoc,b.dataset.citeClause);return;}
 if(b.dataset.jumpClause){document.getElementById('clause-'+b.dataset.jumpClause)?.scrollIntoView({block:'center'});return;}
 if(b.dataset.view){e.preventDefault();navigate(b.dataset.view);return;}
 if(b.dataset.status){statusFilter=b.dataset.status;currentPage=1;render();return;}
 if(b.dataset.queue){navigate('expenses');statusFilter=b.dataset.queue;render();return;}
 if(b.dataset.detail){showDetail(b.dataset.detail);return;}
 if(b.dataset.report){downloadReport(b.dataset.report);return;}
 if(b.dataset.log){showLog(b.dataset.log);return;}
 if(b.dataset.doc){showDoc(b.dataset.doc);return;}
 if(b.dataset.downloadDoc){const d=state.docs.find(d=>d.id===b.dataset.downloadDoc);if(d)download(d.title+(d.builtin?'.md':'.txt'),d.content);return;}
 if(b.dataset.file){openFile(b.dataset.file);return;}
 if(b.dataset.question){askQuestion(b.dataset.question);return;}
 if(b.dataset.page){currentPage=Number(b.dataset.page);document.getElementById('expense-results').innerHTML=expenseResults(filteredExpenses());return;}
 if(b.dataset.removeFile!==undefined){newFiles.splice(Number(b.dataset.removeFile),1);document.getElementById('expense-file-list').innerHTML=fileChips(newFiles);return;}
 const a=b.dataset.action;if(!a)return;
 if(a==='download-knowledge'){download('星澜能源_财务报销制度知识库.md',knowledgeMarkdown());toast('完整虚构知识库已下载');}
 if(a==='open-consult'){role='employee';navigate('consult');}
 if(a==='reset-chat-context'){chatContext={role:DEMO_KNOWLEDGE.defaultRole,city:''};chatMessages=[];render();}
 if(a==='menu'){document.getElementById('sidebar').classList.add('open');document.querySelector('.menu-scrim').classList.add('open');}
 if(a==='close-menu'){document.getElementById('sidebar').classList.remove('open');document.querySelector('.menu-scrim').classList.remove('open');}
 if(a==='switch-role'){role=role==='finance'?'employee':'finance';department='all';period='2026-10';navigate(role==='finance'?'overview':'employee');}
 if(a==='new-expense')navigate('new');
 if(a==='close-dialog')document.getElementById('detail').close();
 if(a==='export-csv')exportExpenses();
 if(a==='export-logs')exportLogs();
 if(a==='print')window.print();
 if(a==='training'){download('员工报销培训提纲_'+period+'.md',trainingContent());toast('培训提纲已生成并下载');}
 if(a==='backup'){download('财务演示数据_'+stamp().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('记录已备份，二进制附件需单独下载');}
 if(a==='implementation'){download('智能财务工作台_接入清单.md','# 生产接入清单\n\n当前版本：本地交互演示，未连接真实服务。\n\n## 企业数据\n- 正式财务制度与版本/生效日\n- 开票抬头、税号主数据\n- 费用标准、部门、人员、预算\n- 审批权限与流程\n\n## 服务与部署\n- 企业身份认证与按角色、部门的数据授权\n- 受保护的后端数据库及附件存储\n- OCR 提取、字段确认、票据验真、重复检查\n- 真实制度解析、权限化检索与带引用回答\n- 根据企业 WorkBuddy 环境确认可用接入方式\n- OA/ERP 审批接口和审计日志\n- 日志脱敏、备份、保留期限与监控\n\n## 验收\n员工提交→预审→人工复核→退回重提→系统回执，验证权限隔离、重复提交、失败恢复、金额一致性。\n\n前端不应存储服务端 API 密钥。');toast('接入清单已下载');}
 if(a==='sample-expense'){formMemory={title:'郑州项目调研差旅费用',dept:'运营管理部',category:'差旅交通',amount:'1286.50',date:'2026-10-22',invoiceNo:'DEMO-'+Date.now().toString().slice(-8),company:'星澜能源科技有限公司（虚构）',note:'10 月 20–22 日前往郑州进行项目调研，费用包含往返交通及市内公务出行。示例数据，仅用于流程体验。'};newFiles=[{id:'sample-new',name:'示例交通电子发票.pdf',size:246000,sample:true}];restoreForm();document.getElementById('expense-file-list').innerHTML=fileChips(newFiles);toast('已填入示例信息，附件为演示占位');}
 if(a==='save-draft'){rememberForm();state.draft={values:{...formMemory},files:[...newFiles],revisionId};if(persist())toast(revisionId?'补正草稿已保存，下次继续使用原单号':'草稿已保存到本浏览器');}
 if(a==='cancel-revision'){revisionId=null;formMemory={};newFiles=[];state.draft=null;persist();render();toast('已退出补正，原退回申请保留；现在可以另开新单');}
 if(a==='confirm-submit')submitExpense();
 if(a==='approve')reviewExpense('approve');
 if(a==='show-reject'){document.getElementById('reject-container').innerHTML='<form id="reject-form" class="reject-form"><label for="reject-reason">请填写需要补充的内容 *</label><textarea id="reject-reason" rows="3" required maxlength="500" placeholder="例如：请补充 10 月 21 日的网约车行程单。"></textarea><button class="btn danger" style="margin-top:10px">确认退回（演示）</button></form>';document.getElementById('reject-reason').focus();}
 if(a==='revise'){const r=state.expenses.find(r=>r.id===selectedId);if(r&&r.mine&&r.status==='returned'){revisionId=r.id;formMemory={title:r.title,dept:r.dept,category:r.category,amount:String(r.amount),date:r.date,invoiceNo:r.invoiceNo,company:r.company,note:r.note+'\n补充说明：'};newFiles=[...r.files];document.getElementById('detail').close();navigate('new');toast('正在补正原申请，提交后保留原单号与处理历史');}}
});
document.addEventListener('submit',e=>{if(e.target.id==='reject-form'){e.preventDefault();const reason=document.getElementById('reject-reason').value.trim();if(!reason){toast('请填写退回原因');return;}reviewExpense('reject',reason);}if(e.target.id==='reply-form'){e.preventDefault();const l=state.logs.find(l=>l.id===e.target.dataset.logId);const reply=new FormData(e.target).get('reply').trim();if(l&&reply){l.answer=reply;l.source='财务人工补充（演示） · '+stamp();l.resolved=true;persist();document.getElementById('detail').close();render();toast('答复已保存到本地咨询日志');}}});
document.getElementById('detail').addEventListener('click',e=>{if(e.target.id==='detail'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('sidebar').classList.remove('open');document.querySelector('.menu-scrim')?.classList.remove('open');}});
shell();render();
